import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.il0noOp3.js";const g=JSON.parse('{"title":"SMART — enumerated source for the Strategic Migration Assessment","description":"","frontmatter":{},"headers":[],"relativePath":"frameworks/smart-question-set.md","filePath":"frameworks/smart-question-set.md"}'),s={name:"frameworks/smart-question-set.md"};function i(n,e,d,c,h,l){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="smart-—-enumerated-source-for-the-strategic-migration-assessment" tabindex="-1">SMART — enumerated source for the Strategic Migration Assessment <a class="header-anchor" href="#smart-—-enumerated-source-for-the-strategic-migration-assessment" aria-label="Permalink to &quot;SMART — enumerated source for the Strategic Migration Assessment&quot;">​</a></h1><blockquote><p><strong>Source:</strong> <a href="https://learn.microsoft.com/assessments/Strategic-Migration-Assessment/" target="_blank" rel="noreferrer">https://learn.microsoft.com/assessments/Strategic-Migration-Assessment/</a><strong>Framework version:</strong> Not versioned by Microsoft — SMART is a living interactive tool with no published release number. Treat the extraction date below as the version. <strong>Extracted:</strong> 2026-07-31 <strong>Verification method:</strong> Manual read of the SMART landing page plus the five CAF pages it draws on (full list in &quot;Verification method&quot; below). No API or transcript exists for SMART&#39;s own question text — see the warning below.</p></blockquote><p><strong>Enumerated 2026-07-31. Verification method and limits are stated below — read them before quoting any coverage number from this page.</strong></p><p>The audit&#39;s DQ12 records why this file exists: <em>&quot;Writing rules against a framework you have not enumerated is how <code>waf.storage.yaml</code> happened&quot;</em> — a rule file scoring a WAF pillar that does not exist. <code>smart.migration.yaml</code> is written against this enumeration and nothing else, and every rule in it cites an item number from the tables below.</p><h2 id="what-smart-is" tabindex="-1">What SMART is <a class="header-anchor" href="#what-smart-is" aria-label="Permalink to &quot;What SMART is&quot;">​</a></h2><p>Microsoft&#39;s <strong>Strategic Migration Assessment and Readiness Tool</strong> (<a href="https://learn.microsoft.com/assessments/Strategic-Migration-Assessment/" target="_blank" rel="noreferrer">https://learn.microsoft.com/assessments/Strategic-Migration-Assessment/</a>) — a 15-minute multiple-choice readiness questionnaire that prepares an organisation for a scale migration to Azure. It is listed under <strong>Plan</strong> in the Cloud Adoption Framework&#39;s tools and templates (<a href="https://learn.microsoft.com/azure/cloud-adoption-framework/resources/tools-templates" target="_blank" rel="noreferrer">https://learn.microsoft.com/azure/cloud-adoption-framework/resources/tools-templates</a>), whose description names its subject areas: <em>&quot;business planning, training, security, and governance.&quot;</em></p><h2 id="verification-method-—-and-the-one-thing-this-enumeration-is-not" tabindex="-1">Verification method — and the one thing this enumeration is NOT <a class="header-anchor" href="#verification-method-—-and-the-one-thing-this-enumeration-is-not" aria-label="Permalink to &quot;Verification method — and the one thing this enumeration is NOT&quot;">​</a></h2><p><strong>What was read (2026-07-31):</strong></p><table tabindex="0"><thead><tr><th>Source</th><th>What it gave</th></tr></thead><tbody><tr><td>The SMART assessment landing page</td><td>The tool&#39;s stated purpose and its four named subject areas</td></tr><tr><td>CAF <em>Tools and templates</em></td><td>SMART&#39;s placement in the Plan phase</td></tr><tr><td>CAF <em>Plan your migration</em> (<code>migrate/plan-migration</code>)</td><td>The five-step migration sequence and the readiness/skills step</td></tr><tr><td>CAF <em>Select your cloud migration strategies</em></td><td>The 8 R&#39;s and the business-driver-to-strategy mapping</td></tr><tr><td>CAF <em>Build migration plan with Azure Migrate</em> (<code>migrate/concepts-migration-planning</code>)</td><td>Assessment-driven prioritisation and the &quot;start small&quot; sequencing guidance</td></tr><tr><td>CAF <em>Assess your workloads for cloud migration</em></td><td>The named discovery/assessment/migration tooling</td></tr></tbody></table><p><strong>⚠️ Microsoft&#39;s own question TEXT and question NUMBERS are not published.</strong> SMART is delivered only as an interactive assessment; its items are not in the documentation, not in an API, and not extractable from the page, which renders a client-side application shell. Anyone claiming to have transcribed Microsoft&#39;s numbered SMART questions from documentation has invented them.</p><p>So this enumeration is <strong>the published CAF Migrate content SMART assesses readiness against</strong>, organised under SMART&#39;s four stated subject areas plus the two the CAF Migrate sequence adds. The <code>SMART-*</code> identifiers below are <strong>Scout&#39;s</strong>, stable and citable, and they are not Microsoft item numbers. Any coverage percentage published against this file must say so.</p><p><strong>Shelf life.</strong> Microsoft is actively rewriting CAF pages (see the audit&#39;s §8 currency warnings). Re-verify before quoting, and re-date this page when you do.</p><h2 id="the-enumeration" tabindex="-1">The enumeration <a class="header-anchor" href="#the-enumeration" aria-label="Permalink to &quot;The enumeration&quot;">​</a></h2><h3 id="a-—-business-planning-smart-subject-area-1" tabindex="-1">A — Business planning (SMART subject area 1) <a class="header-anchor" href="#a-—-business-planning-smart-subject-area-1" aria-label="Permalink to &quot;A — Business planning (SMART subject area 1)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Source</th><th>Scout can evidence?</th></tr></thead><tbody><tr><td>SMART-A1</td><td>Business goals for the migration are defined and agreed with stakeholders</td><td><code>plan/select-cloud-migration-strategy</code></td><td>❌ Organisational</td></tr><tr><td>SMART-A2</td><td>A business driver is identified per workload, and maps to one of the 8 R&#39;s</td><td><code>plan/select-cloud-migration-strategy</code></td><td>❌ Organisational</td></tr><tr><td>SMART-A3</td><td>A gap analysis exists between each workload&#39;s current and target state</td><td><code>plan/select-cloud-migration-strategy</code></td><td>❌ Organisational</td></tr><tr><td>SMART-A4</td><td>Migration waves are sequenced lowest-risk first, not all-at-once</td><td><code>migrate/concepts-migration-planning</code></td><td>⚠️ Partial — assessment groups</td></tr></tbody></table><h3 id="b-—-people-skills-and-training-smart-subject-area-2" tabindex="-1">B — People, skills and training (SMART subject area 2) <a class="header-anchor" href="#b-—-people-skills-and-training-smart-subject-area-2" aria-label="Permalink to &quot;B — People, skills and training (SMART subject area 2)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Source</th><th>Scout can evidence?</th></tr></thead><tbody><tr><td>SMART-B1</td><td>The team&#39;s Azure and migration-tooling skills have been evaluated</td><td><code>migrate/plan-migration</code></td><td>❌ Organisational</td></tr><tr><td>SMART-B2</td><td>External expertise is engaged where a capability gap was found</td><td><code>migrate/plan-migration</code></td><td>❌ Organisational</td></tr></tbody></table><h3 id="c-—-migration-process-and-tooling-the-caf-migrate-sequence" tabindex="-1">C — Migration process and tooling (the CAF Migrate sequence) <a class="header-anchor" href="#c-—-migration-process-and-tooling-the-caf-migrate-sequence" aria-label="Permalink to &quot;C — Migration process and tooling (the CAF Migrate sequence)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Source</th><th>Scout can evidence?</th></tr></thead><tbody><tr><td>SMART-C1</td><td>An Azure Migrate project exists for the estate being migrated</td><td><code>migrate/concepts-migration-planning</code></td><td>✅ <code>Migration/AzureMigrateProjects</code></td></tr><tr><td>SMART-C2</td><td>Discovery is running — a discovery site is registered and reporting</td><td><code>plan/assess-workloads-for-cloud-migration</code></td><td>✅ <code>Migration/AzureMigrateDiscoverySites</code></td></tr><tr><td>SMART-C3</td><td>Assessments have been created, not just a project</td><td><code>migrate/assessment-report</code></td><td>✅ <code>Migration/AzureMigrateAssessments</code></td></tr><tr><td>SMART-C4</td><td>Database workloads have a migration path — DMS or an equivalent</td><td><code>plan/assess-workloads-for-cloud-migration</code></td><td>✅ <code>Migration/DatabaseMigrationServices</code></td></tr><tr><td>SMART-C5</td><td>Bulk data transfer is planned where the volume needs it (Data Box / Stack Edge)</td><td><code>plan/assess-workloads-for-cloud-migration</code></td><td>✅ <code>Migration/DataBox</code>, <code>Migration/StackEdge</code></td></tr><tr><td>SMART-C6</td><td>Migrate projects are not left publicly reachable when private access was intended</td><td><code>migrate/migrate-services-overview</code></td><td>✅ <code>publicNetworkAccess</code> on the project</td></tr></tbody></table><h3 id="d-—-landing-zone-readiness-caf-ready-prerequisite-of-migrate-plan-migration" tabindex="-1">D — Landing zone readiness (CAF Ready, prerequisite of <code>migrate/plan-migration</code>) <a class="header-anchor" href="#d-—-landing-zone-readiness-caf-ready-prerequisite-of-migrate-plan-migration" aria-label="Permalink to &quot;D — Landing zone readiness (CAF Ready, prerequisite of `migrate/plan-migration`)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Source</th><th>Scout can evidence?</th></tr></thead><tbody><tr><td>SMART-D1</td><td>An Azure landing zone exists before workloads are migrated into it</td><td><code>migrate/plan-migration</code> prerequisites</td><td>✅ via the LandingZone assessment</td></tr><tr><td>SMART-D2</td><td>Target subscriptions are organised under a management group hierarchy</td><td>CAF Ready</td><td>✅ <code>Management/ManagementGroups</code></td></tr></tbody></table><h3 id="e-—-security-smart-subject-area-3" tabindex="-1">E — Security (SMART subject area 3) <a class="header-anchor" href="#e-—-security-smart-subject-area-3" aria-label="Permalink to &quot;E — Security (SMART subject area 3)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Source</th><th>Scout can evidence?</th></tr></thead><tbody><tr><td>SMART-E1</td><td>Migrated servers land under Defender for Cloud coverage</td><td>CAF Secure</td><td>✅ <code>Security/DefenderPricing</code></td></tr><tr><td>SMART-E2</td><td>Migration tooling and target resources use private connectivity where required</td><td>CAF Ready</td><td>✅ cross-resource rules (<code>xr.*</code>)</td></tr></tbody></table><h3 id="f-—-governance-smart-subject-area-4" tabindex="-1">F — Governance (SMART subject area 4) <a class="header-anchor" href="#f-—-governance-smart-subject-area-4" aria-label="Permalink to &quot;F — Governance (SMART subject area 4)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Source</th><th>Scout can evidence?</th></tr></thead><tbody><tr><td>SMART-F1</td><td>Policy is applied to the target scope before workloads arrive</td><td>CAF Govern</td><td>✅ <code>Management/PolicyComplianceStates</code></td></tr><tr><td>SMART-F2</td><td>Migrated workloads are brought under backup protection</td><td>CAF Manage — <em>Define reliability requirements</em></td><td>✅ cross-resource rule <code>XR-BKP-01</code></td></tr></tbody></table><h2 id="what-this-means-for-the-rule-file" tabindex="-1">What this means for the rule file <a class="header-anchor" href="#what-this-means-for-the-rule-file" aria-label="Permalink to &quot;What this means for the rule file&quot;">​</a></h2><p>Six of the eighteen items are <strong>organisational</strong> — a tool reading ARM cannot evidence whether a business case was agreed. <code>smart.migration.yaml</code> marks those <code>manual: true</code> with the item cited, so they appear in the report as questions for the customer rather than silently disappearing. That is the difference between &quot;SMART coverage is 12 of 18 automatable&quot; and a fabricated score of 100%.</p>',27)])])}const u=t(s,[["render",i]]);export{g as __pageData,u as default};
